// TH14 synthetic training aliases, native type 0..42.
// Native 0..23 -> modern 0..23; native 24..42 -> modern 25..43.
// Only the alias used by this card is copied; see transcribe/th14/touhou-bullets.ecl.
const TH14_ARROWHEAD: int = 544;   // native type 12, base radius 2.4, colors 0-15

// th14_s1_b4 — TH14 v1.00b st01bs.ecl::BossCard2 (source lines 422-486).
// Source timerReset is at source t=0 = card frame 0; the 120-frame opening buffer
// puts source content at card frame 120. Emission stops at source t=2400
// (setInterrupt(0,0,2400)/spell(6,2400,...)); the remaining window is tail.
//
// Omitted per shared policy: BossItemCard/drops, Ecl_EtBreak cancel wave (no
// incoming bullets in an isolated card), spellEnd, funcSet(0) (no callback set),
// laserCancel (no lasers), playSound, ANM calls, MISS/BOMB/CAPTURE bookkeeping.
// BossCard2_at's initial etAngle(RANDRAD) is overwritten by the per-shot angle
// before any etOn, so it has no behavioural effect and is not re-sampled.
// TraceEnemyPos($UNKNOWN9) (+ moveEnmRel, source -9909 parent id) writes only the
// REL layer; this boss keeps REL=0 (movePosTime/moveRand act on ABS), so it has no
// positional effect; the target has no REL layer. See report.md.

const TIME_LIMIT: int = 2884;      // 120 opening + 2400 attack + 360 tail + 4
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 2400;
const SPELL_OVER_SLOT: int = 16;   // free globals slot: attack-stopped flag

// BossCard2_at EX chain: etEx(ANIM a=1) birth animation omitted; etEx(WAIT a=60)
// then etExSet(index2, type=8 ANGLE_ACCEL, a=60, r=difficulty, s=0).
// set_accel is the along-direction acceleration (px/frame^2); s=0 leaves the
// fired angle untouched.
xformdef SCALE_WAVE(accel: fx) {
    wait(60);
    set_accel(accel);
    wait(60);
    set_accel(0fx);
}

// moveRand(60, mode, speed) ABS step, recipe from transcribe/th16/movement.md
// adapted to this card's moveLimit(0,192,280,56): inner band x+-70, y 178..206;
// per-frame clamp x[-140,140], y[164,220]; speed(k)=v*(1-k/60), k=1..60.
// Shared state: int slot0 = next step count, fx0/fx1 = unit direction,
// fx2 = this moveRand's start speed.
sub boss_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var spd: fx = 0fx;
    if k < 60 { spd = self_fx(2) * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * spd;
    var ny: fx = $self_y + self_fx(1) * spd;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 164fx { ny = 164fx; }
    if ny > 220fx { ny = 220fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// 412 moveRand direction selection (same formula as the TH16 sample, using this
// card's inner band). One signed float, plus one WORD only in the central branch.
sub boss_rand(vmax: fx) {
    set_self_fx(2, vmax);
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 178fx {
        if a < 0 { a = -a; }
    } else if $self_y > 206fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    boss_arm_next_step();
}

// Source frame clock (int slot1) starts at source t=0; emission stops exactly at
// SOURCE_LIMIT, where the interrupt would run BossDead.
sub boss_tick() {
    wait(1);
    var t: int = self_int(1) + 1;
    set_self_int(1, t);
    if t >= SOURCE_LIMIT { set_global(SPELL_OVER_SLOT, 1); }
    boss_arm_next_step();
}

sub boss_wait(n: int) {
    for i in 0..n {
        if self_int(1) >= SOURCE_LIMIT { return; }
        boss_tick();
    }
}

// BossCard2At (kind 0) / BossCard2At2 (kind 1) + BossCard2_at turret.
// The source children are plain shooters: flagSet 288/300 has 0x20 (no body/no
// damage) and only kind 0's 300 additionally has 0x4|0x8 (skip offscreen cull).
// They are represented as owner-bound tasks (no body, no slots needed); the
// source movePos(-112,64)/(112,64) writes the ABS layer, so positions here are
// absolute. TraceEnemyPos is a REL-layer no-op here (see header).
// Local timeline: t=0 teleport (invisible, no firing), t=10..149 the
// BossCard2Move waits and the 1-shot-per-frame turret; the enemy's delete at
// source t=150 ends the coroutine (the 400 count is only a cap).
async sub card2_at(kind: int, color: int) {
    var x: fx = -112fx;
    var y: fx = 64fx;
    var move_ang: angle = 0deg;
    var delta: angle = -3deg;      // moveAngleTime(120, 7, -0.05235988)
    var fire_ang: angle = 180deg;  // BossCard2_at(A=pi, B=-0.2617994)
    var fire_step: angle = -15deg;
    if kind == 1 {
        x = 112fx;
        move_ang = 180deg;         // moveAngle(pi)
        delta = 3deg;              // moveAngleTime(120, 7, +0.05235988)
        fire_ang = 0deg;           // BossCard2_at(0, +0.2617994)
        fire_step = 15deg;
    }
    var accel: fx = 0.025fx;       // !E / !N
    var rank: int = global(GVAR_RANK);
    if rank == 2 { accel = 0.035fx; }       // !H
    if rank >= 3 { accel = 0.05fx; }        // !LO
    wait(10);                      // child movePos then wait(10)
    var u: int = 0;
    while u < 140 {                // reaches the source delete at local t=150
        if global(SPELL_OVER_SLOT) != 0 { return; }   // BossDead enmKillAll
        // Birth ANIM a=1 keeps its position -= 4*velocity (=0.4px at 0.1).
        var bx: fx = x - 0.4fx * cos(fire_ang);
        var by: fx = y - 0.4fx * sin(fire_ang);
        _ = fire(TH14_ARROWHEAD, color, bx, by, 0.1fx, fire_ang,
                 SCALE_WAVE(accel), none);
        fire_ang = fire_ang + fire_step;
        // BossCard2Move speed chain (modes 4/0/0/1) + moveAngleTime mode7.
        var k: int = u + 1;
        var spd: fx = 18fx;
        if k <= 40 {
            var f: fx = ((40 - k) as fx) / 40fx;
            spd = 18fx * (1fx - f * f);
        } else if k <= 60 {
            spd = 8fx * ((k - 40) as fx / 20fx);
        } else if k <= 80 {
            spd = 8fx * (1fx - ((k - 60) as fx / 20fx));
        } else if k <= 120 {
            var g: fx = ((k - 80) as fx) / 40fx;
            spd = 18fx * g * g;
        }
        if u < 120 { move_ang = move_ang + delta; }
        x = x + spd * cos(move_ang);
        y = y + spd * sin(move_ang);
        // kind 1 lacks flag 0x4|0x8: offscreen recycling ends the child.
        if kind == 1 && (x < -192fx || x > 192fx || y < 0fx || y > 448fx) { return; }
        u = u + 1;
        wait(1);
    }
}

// Boss slot0 render state from Boss context_only: setHitbox(48,48)->r24,
// setHurtbox(40,40)->r20. The training shell keeps the boss invulnerable.
async sub boss() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    set_self_fx(2, 0fx);
    set_self_int(0, 0);
    set_self_int(1, 0);
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);   // movePosTime(60,4,0,192)
    boss_wait(120);                            // wait(120)
    var A: int = 300;                          // diffI($A,300,300,220,120)
    if global(GVAR_RANK) == 2 { A = 220; }
    if global(GVAR_RANK) >= 3 { A = 120; }
    while self_int(1) < SOURCE_LIMIT {
        spawn card2_at(0, 10);                 // $I0=10 enmCreate("BossCard2At")
        boss_wait(60);
        boss_rand(0.8fx);
        if global(GVAR_RANK) >= 1 {            // !NHL
            spawn card2_at(1, 8);
            boss_wait(60);
            boss_rand(2.0fx);
        }
        if global(GVAR_RANK) >= 2 {            // !HL
            spawn card2_at(0, 6);
            boss_wait(60);
            boss_rand(2.0fx);
        }
        if global(GVAR_RANK) >= 3 {            // !L
            spawn card2_at(1, 4);
            boss_wait(60);
            boss_rand(2.0fx);
        }
        boss_wait(A);
        if A > 60 { A = A - 60; }
    }
    // BossDead boundary context: emissions already stopped at t=2400; etClearAll
    // runs 60 frames later (stars omitted with the drop policy).
    wait(60);
    clear_bullets_at(0fx, 0fx, 1024fx, 0);
}

async sub card2_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1900, 0, 0, 0, boss);  // entry representative (0,128)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, card2_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    set_global(SPELL_OVER_SLOT, 0);
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
